mkdir -p modules/account/hooks && cat > modules/account/lib/api-client.ts <<'EOF'
import { parseV3ApiError } from "@/modules/api/lib/v3-client";
import type { TUserDataExport } from "./user-data-export";

const ENDPOINT = "/api/v3/account/data-export";

/** Client fetcher for the signed-in user's data export. */
export async function fetchUserDataExport(): Promise<TUserDataExport> {
  const response = await fetch(ENDPOINT, { method: "GET", cache: "no-store" });
  if (!response.ok) {
    throw await parseV3ApiError(response);
  }
  return ((await response.json()) as { data: TUserDataExport }).data;
}
EOF
cat > modules/account/lib/query.ts <<'EOF'
/** Typed query-key factory for the account module. Never inline string keys. */
export const accountKeys = {
  all: ["account"] as const,
  dataExport: () => [...accountKeys.all, "data-export"] as const,
};
EOF
cat > modules/account/hooks/use-user-data-export.ts <<'EOF'
"use client";

import { useMutation } from "@tanstack/react-query";
import { fetchUserDataExport } from "@/modules/account/lib/api-client";
import { accountKeys } from "@/modules/account/lib/query";

/** Fetches the signed-in user's data export on demand; the caller decides what to do with the result. */
export const useUserDataExport = () =>
  useMutation({
    mutationKey: accountKeys.dataExport(),
    mutationFn: fetchUserDataExport,
  });
EOF
cat > modules/account/components/query-client-provider.tsx <<'EOF'
"use client";

import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { type ReactNode, useState } from "react";

/** Provider for the account profile's client components. Created once per mount so the cache is not shared across requests. */
export const AccountQueryClientProvider = ({ children }: Readonly<{ children: ReactNode }>) => {
  const [queryClient] = useState(
    () =>
      new QueryClient({
        defaultOptions: { queries: { refetchOnWindowFocus: false } },
      })
  );

  return <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>;
};
EOF
cat > "app/(app)/workspaces/[workspaceId]/settings/account/profile/components/DownloadMyDataButton.tsx" <<'EOF'
"use client";

import toast from "react-hot-toast";
import { useTranslation } from "react-i18next";
import { useUserDataExport } from "@/modules/account/hooks/use-user-data-export";
import { Button } from "@/modules/ui/components/button";

const DOWNLOAD_FILE_NAME = "formbricks-user-data.json";

const saveJsonFile = (data: unknown, fileName: string) => {
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  link.style.display = "none";
  document.body.appendChild(link);
  try {
    link.click();
  } finally {
    link.remove();
    // Revoked on the next task: some browsers read the URL only after `click()` has returned.
    setTimeout(() => URL.revokeObjectURL(url), 0);
  }
};

export const DownloadMyDataButton = () => {
  const { t } = useTranslation();
  const dataExport = useUserDataExport();

  const handleDownload = () => {
    dataExport.mutate(undefined, {
      onSuccess: (data) => saveJsonFile(data, DOWNLOAD_FILE_NAME),
      onError: () => toast.error(t("common.something_went_wrong_please_try_again")),
    });
  };

  return (
    <Button variant="secondary" size="sm" onClick={handleDownload} loading={dataExport.isPending}>
      {t("workspace.settings.profile.download_my_data")}
    </Button>
  );
};
EOF
